import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const findProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
const listTasks = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const findTask = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const taskData = task => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['index.html', 'text/html; charset=utf-8']],
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
  ['/style.css', ['style.css', 'text/css; charset=utf-8']],
]);

function json(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

async function readBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try { return JSON.parse(body); } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') {
      return json(res, 200, { status: 'ok' });
    }
    if (path === '/api/projects' && req.method === 'GET') {
      return json(res, 200, listProjects.all());
    }
    if (path === '/api/projects' && req.method === 'POST') {
      const data = await readBody(req);
      const name = typeof data?.name === 'string' ? data.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(res, 201, findProject.get(Number(result.lastInsertRowid)));
    }
    const apiProject = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && apiProject) {
      const project = findProject.get(Number(apiProject[1]));
      return project ? json(res, 200, project) : json(res, 404, { error: 'Project not found' });
    }
    const taskRoute = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskRoute) {
      const projectId = Number(taskRoute[1]);
      const taskId = taskRoute[2] ? Number(taskRoute[2]) : null;
      if (!findProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
      if (req.method === 'GET' && taskId === null) {
        return json(res, 200, listTasks.all(projectId).map(taskData));
      }
      if (req.method === 'POST' && taskId === null) {
        const data = await readBody(req);
        const title = typeof data?.title === 'string' ? data.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title);
        return json(res, 201, taskData(findTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (req.method === 'PATCH' && taskId !== null) {
        if (!findTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
        const data = await readBody(req);
        if (typeof data?.completed !== 'boolean') return json(res, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(data.completed), projectId, taskId);
        return json(res, 200, taskData(findTask.get(projectId, taskId)));
      }
    }
    if (req.method === 'GET') {
      const asset = /^\/projects\/\d+$/.test(path) ? assets.get('/') : assets.get(path);
      if (asset) {
        res.writeHead(200, { 'Content-Type': asset[1] });
        return res.end(readFileSync(join(root, 'public', asset[0])));
      }
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(res, error.status, { error: error.message });
    console.error(error);
    if (!res.headersSent) json(res, 500, { error: 'An unexpected error occurred' });
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}
const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function showError(message) {
  const alert = document.querySelector('#error');
  alert.textContent = message;
  alert.hidden = false;
}

function projectRow(project) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = 'Open project';
  button.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
  row.append(name, button);
  return row;
}

async function render() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.innerHTML = `
      <button type="button" id="back" class="secondary">Projects</button>
      <h1></h1>
      <form id="create-task" novalidate>
        <label for="task-title">Task title</label>
        <div class="form-controls">
          <input id="task-title" name="title" type="text" autocomplete="off">
          <button type="submit">Create task</button>
        </div>
      </form>
      <p id="error" role="alert" hidden></p>
      <h2>Tasks</h2>
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option value="all">All</option>
        <option value="open">Open</option>
        <option value="completed">Completed</option>
      </select>
      <p id="empty" hidden>No tasks match this filter.</p>
      <ul id="tasks" aria-label="Tasks"></ul>`;
    document.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
    const project = await request(`/api/projects/${match[1]}`);
    document.querySelector('h1').textContent = project.name;
    document.title = `${project.name} · Workboard`;
    const endpoint = `/api/projects/${project.id}/tasks`;
    const tasks = await request(endpoint);
    const filter = document.querySelector('#task-filter');
    const list = document.querySelector('#tasks');
    function renderTasks() {
      const visible = tasks.filter(task => filter.value === 'all' ||
        (filter.value === 'completed' ? task.completed : !task.completed));
      list.replaceChildren(...visible.map(task => {
        const row = document.createElement('li');
        row.dataset.testid = 'task-row';
        const title = document.createElement('span');
        title.textContent = task.title;
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          document.querySelector('#error').hidden = true;
          try {
            const updated = await request(`${endpoint}/${task.id}`, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            Object.assign(task, updated);
            renderTasks();
          } catch (error) {
            checkbox.checked = task.completed;
            showError(error.message);
          } finally { checkbox.disabled = false; }
        });
        row.append(title, checkbox);
        return row;
      }));
      document.querySelector('#empty').hidden = visible.length !== 0;
    }
    filter.addEventListener('change', renderTasks);
    renderTasks();
    document.querySelector('#create-task').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#task-title');
      const title = input.value.trim();
      document.querySelector('#error').hidden = true;
      if (!title) { showError('Task title is required'); input.focus(); return; }
      const button = event.currentTarget.querySelector('button');
      button.disabled = true;
      try {
        tasks.push(await request(endpoint, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        }));
        renderTasks();
        input.value = '';
        input.focus();
      } catch (error) { showError(error.message); }
      finally { button.disabled = false; }
    });
  } else {
    app.innerHTML = `
      <h1>Workboard</h1>
      <p class="intro">A place for your projects.</p>
      <form id="create-project" novalidate>
        <label for="project-name">Project name</label>
        <div class="form-controls">
          <input id="project-name" name="name" type="text" autocomplete="off">
          <button type="submit">Create project</button>
        </div>
      </form>
      <p id="error" role="alert" hidden></p>
      <h2>Projects</h2>
      <p id="empty" hidden>No projects yet. Create one to get started.</p>
      <ul id="projects" aria-label="Projects"></ul>`;
    const projects = await request('/api/projects');
    const list = document.querySelector('#projects');
    list.append(...projects.map(projectRow));
    document.querySelector('#empty').hidden = projects.length !== 0;
    document.querySelector('form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const input = document.querySelector('#project-name');
      const name = input.value.trim();
      document.querySelector('#error').hidden = true;
      if (!name) { showError('Project name is required'); input.focus(); return; }
      const button = event.currentTarget.querySelector('button');
      button.disabled = true;
      try {
        const project = await request('/api/projects', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        list.append(projectRow(project));
        document.querySelector('#empty').hidden = true;
        input.value = '';
        input.focus();
      } catch (error) { showError(error.message); }
      finally { button.disabled = false; }
    });
  }
}

render().catch(error => {
  if (!document.querySelector('#error')) app.innerHTML = '<p id="error" role="alert"></p>';
  showError(error.message);
}).finally(() => app.setAttribute('aria-busy', 'false'));
